INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65388761', 65388761, 'analyze_legacy', 'Kab. Luwu Timur', 'kabkota', 'Dinas Perdagangan, Koperasi, UKM Dan Perindustrian', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat Tulis Kantor', 'Barang', 'E-Purchasing', 'Sulawesi Selatan, Luwu Timur (Kab.)', 3176700, 'February 2026', 'APBD', 1, 1, '1 Paket', '1. Binder Clips no. 260 5 pack @Rp24.300 2. Balpoint non gel 2 dos @Rp31.100 3. foto copy 4506 lembar @Rp350 4. Map kertas 3 pak @Rp39.600 5. Map Snalhekter 16 pak @Rp30.300 6. Pelubang kertas Uk. sedang 1 buah @Rp58.700 7. Blangko cek bank 2 eksemplar @Rp300.000 8. Jilid biasa 12 eksemplar @Rp12.800', '1. Binder Clips no. 260 Merek : Joyko, tipe : 260, satuan : dus, isi : 12 buah, bahan : besi, jenis : penjepit, ukuran : 5,1 cm X 8 cm x 2.1 cm, berat : 255 gram, warna : hitam Satuan Barang Dus 2. BalpointMerk : Snowman, Tipe : Snowman V-1, Satuan : dus, isi : 12 buah, tebal tulisan : 0,7 mm, Berat Satuan : 9 g, Ukuran : Panjang 15.5 cm x Diameter 1.1 cm, Jenis : Pulpen Tinta Biasa, Warna tinta : hitam, 3 warna, hitam, merah dan biru, Pulpen dengan bodi kaca 3. foto copy Jenis Bahan: Kertas A4 da F4, Ukuran / Dimensi: Kertas A4 dan F4 4. Map kertasmap kertas bufallo, Bahan Kertas,Isi 50 buah Ukuran Kertas Folio, Tersedia pilihan warna sesuai stock yang tersedia, untuk menyimpan dokumen 5. Map Snalhekter Merek: Jenia Bahan: Plastik Ukuran: Panjang: 34,5 cm Lebar: 23 cm Berat: 40 gram per unit, Tipe Snelhecter dengan pengait kertas di bagian tengah untuk menyimpan dokumen yang telah dilubangi. Bagian depan transparan untuk memudahkan identifikasi dokumen. Tersedia dalam berbagai pilihan warna. Kapasitas: Dapat menampung sejumlah dokumen berukuran folio. Kemasan: 1 pak berisi 12 pcs. Business File Jenia dirancang untuk menyimpan dan mengorganisir dokumen Anda dengan rapi dan efisien. Dengan bahan plastik berkualitas dan desain fungsional, produk ini menjadi pilihan ideal untuk kebutuhan arsip Anda. 6. Pelubang kertas Uk. sedang Merk : Joyko, Tipe : No. 40, ukuran sedang, 2 lubang, Ukuran : 11.4 x 8.2 x 8.9 cm, kapasitas muatan kertas : 2 mm, Diameter lubang hasil pembolong : 6 mm, Jarak antara lubang pertama dan kedua hasil pembolong : 80 mm, Terdapat Guide Ruler ( Ukuran maksimum A4 ), terdapat Penggaris Untuk Mengukur Kertas 7. Blangko cek bank mencakup nomor seri, nama bank, nominal, tanggal, dan tanda tangan sah. Cek berfungsi sebagai alat pembayaran tunai/pemindahbukuan, umumnya berbentuk fisik kertas khusus dengan fitur keamanan. 8. Jilid biasa Jasa jilid biasa, bahan : kertas jilid, lakban, peluru hekter, plastik bening, untuk menyatukan dokumen dengan sampul depan dilapisi plastik mika tidak mudah kotor', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2111889);
