INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65388950', 65388950, 'analyze_legacy', 'Kab. Luwu Timur', 'kabkota', 'Dinas Perdagangan, Koperasi, UKM Dan Perindustrian', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat Tulis Kantor', 'Barang', 'E-Purchasing', 'Sulawesi Selatan, Luwu Timur (Kab.)', 3849200, 'February 2026', 'APBD', 1, 1, '1 Paket', '1. Pena penyorot 3 buah @17.3000 2. Binder Clips 2 box @24.300 3. Balpoint Gel 2 pack @48.900 4. Foto Copy 8172 lembar @350 5. Jilid Biasa 13 eksamplar @12.800 6. Jilid Spiral 15 eksamplar @35.500 7. Penghapus/ cairan koreksi 4 buah @6.200 8. Stick Note 4 Buah @20.500', '1. Pena penyorot Merk : Boss, Tipe : Stabilo (Highlighter) , Satuan : buah, Memiliki 2 ketebalan garis, 2 mm dan 5 mm, warna : kuning, biru, hijau, merah, orange, pink, lavender (ungu) , ukuran produk P 18 cm x L 1 cm x T 1 cm (18 cm3) 2. Binder Clips Merek : Joyko, tipe : 260, satuan : dus, isi : 12 buah, bahan : besi, jenis : penjepit, ukuran : 5,1 cm X 8 cm x 2.1 cm, berat : 255 gram, warna : hitam Satuan Barang Dus 3. Balpoint Gel Merk : Stinta water-based yang smooth, (tipe jarum atau peluru), desain ergonomis, dan beberapa seri memiliki fitur water resistant 4. Foto Copy Jenis Bahan: Kertas A4 da F4, Ukuran / Dimensi: Kertas A4 dan F4 5. Jilid Biasa, Jasa jilid biasa, bahan : kertas jilid, lakban, peluru hekter, plastik bening, ketebalan 100 halaman, untuk menyatukan dokumen dengan sampul depan dilapisi plastik mika tidak mudah kotor 6. jilid spiral, jasa jilid spiral besi (kawat), bahan : plastik laminating, kertas jilid, spiral besi (kawat), Ketebalan 250 lembar, hasil jilid rapi, menarik lebih kuat, sampul depan dan belakang dilapisi plastik tidak mudah kotor dan rusak, isi dokumen mudah diganti dengan sistem jilid besi (kawat) 7. Penghapus/cairan koreksi Merk : Esco, Tipe : CW209 (Mika), satuan : botol, Jenis : penghapus pulpen cair, Warna putih, Ukuran: 4 x 2 x 9,5 cm, Isi: 7 ml 8. Stick Note Jenis : Sticky Notes dengan 8 warna yang berbeda - Bahan : Kertas dengan perekat yang kuat dan tidak meninggalkan residu - Jumlah Lembar : Bervariasi, tergantung pada ukuran dan jenis Sticky Notes - ukuran : 76 x 76 mm - isi : 200 lembar (25 lembar x 8) - warna : 8 warna (Merah, Biru, Hijau, Kuning, Ungu, Jingga, Pink, Putih) - berat : 50 gram - bentuk : persegi panjang', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2111930);
