INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65385210', 65385210, 'analyze_legacy', 'Kab. Luwu Timur', 'kabkota', 'Dinas Perdagangan, Koperasi, UKM Dan Perindustrian', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat/Bahan untuk Kegiatan Kantor Lainnya', 'Barang', 'Pengadaan Langsung', 'Sulawesi Selatan, Luwu Timur (Kab.)', 243480000, 'June 2026', 'APBD', 1, 1, '1 Paket', 'Angkatan ke dua KMP : Cetak spanduk; 3 Mtr x 1 Mtr x 1 lembar @Rp.90.000 Angkatan pertama KMP : Cetak spanduk; 3 Mtr x 1 Mtr x 1 lembar @Rp.90.000 Cetak spanduk; 3 Mtr x 1 Mtr x 1 lembar @Rp.90.000 Kegiatan Harkopnas : 1. Jasa Akomodasi dan transpor penari tradisional; 1 Keg. x 2 Org @Rp. 5.000.000 2. Jasa band lokal; 1 hari @Rp.15.000.000 3. Jasa juri perlombaan (3 org juri utk lomba nyanyi) 9 org x 1 keg. @Rp.1.000.000 4. Jasa MC pentas seni budaya; 2 org x 1 keg. @Rp.500.000 5. Jasa MC perlombaan; 2 0rg x 3 hari @Rp.500.000 6. Keg. Donor Darah; 1 paket @Rp.7.900.000 7. Perlengkapan jalan santai anti mager plus hadia; 1 paket @Rp.69.000.000 8. Publikasi media cetak/elektronik; 1 paket @Rp.5.000.000 9. Sewa AC portable; 4 buah x 1 keg. @Rp.3.750.000 10. Sewa kursi; 2000 buah x 1 keg. @Rp.5.000 11. Cetak spanduk; 3 Mtr x 1 Mtr x 1 Lembar @Rp.90.000 12. Gody Bag+Produk Khas; 1 kali x 150 org @Rp.150.000 13. Cetak baliho;1 paket @Rp.30.000.000 14. Cetak umbul-umbul; 300 buah @Rp.100.000 15. Kembang api bahan campuran; 1 paket @Rp.15.000.000', 'Angkatan ke dua KMP : Cetak Spanduk; Spanduk dengan bahan Khusus baik untuk autdoor dan indoor Angkatan pertama KMP : Cetak Spanduk; Spanduk dengan bahan Khusus baik untuk autdoor dan indoor Cetak Spanduk; Spanduk dengan bahan Khusus baik untuk autdoor dan indoor Kegiatan Harkopnas : 1. Jasa Akomodasi dan transpor penari tradisional; jenis mobil bus, van atau truk yang dilengkapi fasilitas keamanan dan kenyamanan bisa di lengkapi dengan AC saus sistem dan tempat menyimpan kostum peralatan. 2. Jasa band lokal; jenis musik disesuaikan dengan tema acara, jumlah pesonil 2-5 orang peralatan saund system instrumen dan lampu 3. Jasa juri perlombaan; kriteria penilaian disesuikan dengan jenis lomba, juri ahli di bidangnya 4. Jasa MC pentas seni budaya; jenis pertunjukan tarian, musik dan teater biaya di sesuaikan dengan jenis pertunjukan jumlah penampil dan durasi 5. Jasa MC perlombaan;jenis pertunjukan tarian, musik dan teater biaya di sesuaikan dengan jenis pertunjukan jumlah penampil dan durasi 6. Keg. Donor Darah; waktu di sesuaikan dengan jadwal PMI atau fasilitas kesehatan 7. Perlengkapan jalan santai anti mager plus hadia; lokasi taman, alun-alun atau jalur khusus jalan santai 8. Publikasi media cetak/elektronik; jenis e-book, e-newpaper atau e-flyer 9. Sewa AC portable; kapasitas pendinginan ;5.000-12.000 btu daya ; 500-1.500 watt 10. Sewa kursi; Jenis kursi plastik, kursi lipat atau kursi sofa, warna di sesuikan dengan kebutuhan 11. Cetak spanduk; ukuran di sesuikan dengan kebutuhan bahan vinyl atau besi warna full color 12. Gody Bag+Produk Khas; bahan kain tebal ukuran di sesuaikan dengan kebutuhan fitur bisa termaksud tali resleting atau label indentitas 13. Cetak baliho; bahan vinyl atau flexi warna full color 14. Cetak umbul-umbul; bahan vinyl atau flexi warna full color 15. Kembang api bahan campuran; jenis campuran berbagai efek bisa termaksud ledakan warna cahaya atau asap dan suara', 15000000, 'high', 'Terdapat komponen pengadaan kembang api dalam kegiatan kantor/peringatan yang tidak esensial terhadap fungsi layanan publik dan berpotensi menimbulkan kesan penggunaan APBD untuk atraksi seremonial. Berdasarkan rincian yang tersedia, komponen ini layak dikategorikan tidak pantas untuk dicermati lebih lanjut.', NULL, NULL, 3, 1, 1, 1, 1, 2114256);
