INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65389002', 65389002, 'analyze_legacy', 'Kab. Luwu Timur', 'kabkota', 'Dinas Perdagangan, Koperasi, UKM Dan Perindustrian', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Alat Tulis Kantor', 'Barang', 'E-Purchasing', 'Sulawesi Selatan, Luwu Timur (Kab.)', 2315800, 'February 2026', 'APBD', 1, 1, '1 Paket', '1. Pena penyorot 3 buah @17.3000 2. Balpoint Gel 2 pack @48.900 3. Foto Copy 3836 lembar @350 4. Jilid Biasa 17 eksamplar @12.800 5. Jilid Spiral 11 eksamplar @34.500 6. Map Ordner 3 buah @35.400 7. Pelubang Kertas Uk Sedang 1 buah @58.700 8. Stick Note 3 Buah @20.500', '1. Pena penyorot Merk : Boss, Tipe : Stabilo (Highlighter) , Satuan : buah, Memiliki 2 ketebalan garis, 2 mm dan 5 mm, warna : kuning, biru, hijau, merah, orange, pink, lavender (ungu) , ukuran produk P 18 cm x L 1 cm x T 1 cm (18 cm3) 2. Balpoint Gel Merk : Snowman, Tipe : V-5, Satuan : dus, isi : 12 buah, tebal tulisan : 0,7 mm, Berat Satuan : 50 g, Ukuran : Panjang = 15 cm, Jenis : Pulpen Tinta Biasa, Pulpen Tindis, Terdapat Jepitan, Warna hitam, biru dan merah, ukuran produk P 15 cm x L 7 cm x T 3 cm (315 cm3) 3. Foto Copy Jenis Bahan: Kertas A4 da F4, Ukuran / Dimensi: Kertas A4 dan F4 4. Jilid Biasa, Jasa jilid biasa, bahan : kertas jilid, lakban, peluru hekter, plastik bening, ketebalan 100 halaman, untuk menyatukan dokumen dengan sampul depan dilapisi plastik mika tidak mudah kotor 5. jilid spiral, jasa jilid spiral besi (kawat), bahan : plastik laminating, kertas jilid, spiral besi (kawat), Ketebalan 250 lembar, hasil jilid rapi, menarik lebih kuat, sampul depan dan belakang dilapisi plastik tidak mudah kotor dan rusak, isi dokumen mudah diganti dengan sistem jilid besi (kawat) 6. Pelubang Kertas Uk Sedang Merk : Joyko, Tipe : No. 40, ukuran sedang, 2 lubang, Ukuran : 11.4 x 8.2 x 8.9 cm, kapasitas muatan kertas : 2 mm, Diameter lubang hasil pembolong : 6 mm, Jarak antara lubang pertama dan kedua hasil pembolong : 80 mm, Terdapat Guide Ruler ( Ukuran maksimum A4 ), terdapat Penggaris Untuk Mengukur Kertas, pembolong kertas dua lubang berukuran medium (sedang) 7. Map Ordner Lebar: 7,5 cm, Tinggi: sekitar 32 cm, Tebal: sekitar 8-10 cm, Bahan: Plastik berkualitas dan tebal, Fitur :Dilengkapi dengan fastener besi untuk mengunci dokumen, Label yang dapat diganti-ganti di bagian depan box untuk memudahkan pengelompokkan dokumen, Warna: Tersedia dalam beberapa warna, yaitu : Merah, Hijau muda, Hijau tua, Biru, Kuning, Orange, Hitam 8. Stick Note Jenis : Sticky Notes dengan 8 warna yang berbeda - Bahan : Kertas dengan perekat yang kuat dan tidak meninggalkan residu - Jumlah Lembar : Bervariasi, tergantung pada ukuran dan jenis Sticky Notes - ukuran : 76 x 76 mm - isi : 200 lembar (25 lembar x 8) - warna : 8 warna (Merah, Biru, Hijau, Kuning, Ungu, Jingga, Pink, Putih) - berat : 50 gram - bentuk : persegi panjang', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2114478);
