INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65432214', 65432214, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'Pendidikan dan Pelatihan Anti Pencucian Uang PPATK', 'Pengadaan Pemeliharaan AC Presisi Pada Pusdiklat APUPPT Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Depok (Kota)', 100000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 2, Unit, @ 50000000 )', 'Pengadaan Pemeliharaan AC Presisi Pada Pusdiklat APUPPT Tahun Anggaran 2026', 'Pemeliharaan dilakukan untuk memantau kinerja unit, menjaga keandalan sistem, serta mencegah terjadinya gangguan atau kerusakan yang dapat muncul di masa mendatang. Kegiatan pemeliharaan juga berfungsi sebagai upaya preventif dalam memastikan AC Presisi selalu berada dalam kondisi siap operasi. Spesifikasi Mutu/Kualitas: a. AC Presisi berfungsi normal dan andal dalam menjaga suhu dan kelembapan Data Center tanpa mengganggu perangkat TI. b. Pemeliharaan dilakukan secara rutin oleh Penyedia yang ditetapkan melalui proses Pengadaan Barang/Jasa. c. Penyedia meenyediakan layanan emergency call dengan waktu respons paling lambat hari kerja berikutnya (next business day). d. Tanggapan atas laporan keluhan diberikan maksimal 12 (dua belas) jam sejak laporan diterima. e. Setiap pekerjaan didukung dengan laporan dan dokumentasi pelaksanaan pemeliharaan. Spesifikasi Pekerjaan Pemeliharaan: a. Pekerjaan Pembersihan • Pembersihan air filter pada unit indoor • Pembersihan condenser / unit oudoor • Pembersihan evaporator (min. 1 kali dalam setahun) • Pembersihan dan vacuuming pipa dan sistem drainase/kondensat b. Pemeriksaan Sistem Mekanikal & Refrigerasi • Pemeriksaan kompresor, termasuk kondisi dan level oli. • Penambahan oli kompresor apabila diperlukan sesuai hasil pemeriksaan • Pemeriksaan jalur pipa refrigerant untuk memastikan tidak terdapat kebocoran • Penambahan refrigerant apabila diperlukan sesuai hasil pemeriksaan • Pemeriksaan seluruh sambungan pipa untuk memastikan tidak terdapat koneksi yang kendor atau tidak aman c. Pemeriksaan Sistem Kelistrikan & Kontrol • Pemeriksaan panel kelistrikan unit AC Presisi • Pemeriksaan dan verifikasi parameter CRAC Controller • Pemeriksaan sistem reheat d. Pemeriksaan Lingkungan Data Center • Pemeriksaan sistem pengatur kelembapan • Pengukuran serta pencatatan suhu dan kelembapan ruangan Data Center e. Pengujian Akhir • Pelaksanaan final check/functional test untuk memastikan unit berfungsi normal setelah pemeliharaan f. Pelaporan • Penyusunan laporan hasil preventive maintenance per unit. • Laporan dilengkapi dengan dokumentasi foto dan rekomendasi teknis bila diperlukan g. Ketentuan Teknis • Pekerjaan sudah termasuk layanan emergency call 24 (dua puluh empat) jam dengan minimal 2 (dua) kali kunjungan selama periode kontrak. • Pekerjaan sudah termasuk jasa penggantian sparepart apabila terjadi kerusakan, tidak termasuk biaya sparepart yang diganti. • Penyedia merupakan authorized partner dari perangkat AC Presisi Liebert yang digunakan oleh Pusdiklat APUPPT Spesifikasi Unit AC Presisi No Uraian Unit AC Presisi Jml Satuan Qty 1. AC Presisi Liebert PEX3 P2040DA 2 Unit 4 visit/tahun 2.DAK Tenaga Teknis: Personel memiliki pengalaman menangani PAC/Data Center minimal 1 tahun. Personel memahami sistem kelistrikan, refrigerasi, dan kontrol suhu/kelembapan. Diutamakan berasal dari atau didukung authorized partner Liebert, serta mematuhi K3. Peralatan: Alat ukur kelistrikan dan regrigerant, alat ukur suhu dan kelembapan, peralatan pembersihan dan pemeliharaan AC Presisi, serta peralatan keselamatan kerja dan dokumentasi. Spesifikasi Wakti: 11 Bulan dari Februari s/d 31 Desember 2026 Gedung Pusdiklat APUPPT Jalan Raya Tapos Nomor 82, Kelurahan Cimpaeun, Kecamatan Tapos, Kota Depok, Jawa Barat. 16459', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2117372);
