INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65396629', 65396629, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Jasa Konsultan Penyusunan Dokumen Analisis Pengembangan Sistem Teknik Lingkungan Pada Kegiatan Koordinasi Program Swasembada Air', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Mendukung program pendampingan sanitasi (Percepatan Pembangunan Sanitasi Permukiman/PPSP) kepada Pemerintah Daerah; 2. Memfasilitasi pemerintah daerah dalam penyusunan/pemutakhiran dokumen perencanaan sanitasi seperti SSK (Strategi Sanitasi Kota/Kabupaten); 3. Menelaah dan menganalisis isu serta bottleneck dalam perencanaan sanitasi dan infrastrukturnya di Tingkat daerah; 4. Menyiapkan materi pembelajaran dan peningkatan kapasitas serta mendiseminasikannya kepada Pemerintah Daerah di bawah program pendampingan PPSP; 5. Menelaah keterkaitan dan sinkronisasi antara dokumen perencanaan daerah dengan dokumen perencanaan nasional; dan 6. Menyusun laporan bulanan Jasa Konsultan Junior Teknik Lingkungan.', '1. Pendidikan minimal S1 teknik lingkungan; 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam bidang air minum / sanitasi / persampahan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dibuktikan dengan jumlah kontrak kerja/lama kontrak kerja; 3. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 4. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 5. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 6. Memiliki pengalaman kerja bidang air minum atau sanitasi minimal 3 tahun (dibuktikan dengan kontrak); 7. Memiliki pengalaman dalam penyediaan infrastruktur sanitasi di daerah (dibuktikan dengan kontrak).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2119960);
